#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
namespace DeliveryService.Mok.Editor {
[InitializeOnLoad] public static class DistrictOrdersInstaller {
static DistrictOrdersInstaller(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("Temp/Mok-district-orders-install"))return;File.Delete("Temp/Mok-district-orders-install");try{Run();}catch(Exception e){File.WriteAllText("Temp/Mok-district-orders-install.txt",e.ToString());Debug.LogException(e);}}
static void Run(){var old=SceneManager.GetActiveScene();var stamp=DateTime.Now.ToString("yyyyMMdd-HHmmss");for(int i=0;i<SceneManager.sceneCount;i++)if(!EditorSceneManager.SaveScene(SceneManager.GetSceneAt(i),"Temp/Before-district-orders-"+stamp+"-"+i+".unity",true))throw new Exception("Backup failed");var scene=SceneManager.GetSceneByPath("Assets/Scenes/JJinCity.unity");bool opened=!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene("Assets/Scenes/JJinCity.unity",OpenSceneMode.Additive);SceneManager.SetActiveScene(scene);EditorSceneManager.SaveScene(scene,"Temp/JJinCity-before-district-orders-"+stamp+".unity",true);var all=scene.GetRootGameObjects();var manager=all.SelectMany(g=>g.GetComponentsInChildren<OrderManager>(true)).First();if(manager.GetComponent<DistrictDeliveryPolicy>()!=null)throw new Exception("Already installed; preserve edited policy");var so=new SerializedObject(manager);var list=so.FindProperty("deliveryPoints");var points=Enumerable.Range(0,list.arraySize).Select(i=>list.GetArrayElementAtIndex(i).objectReferenceValue as DeliveryPoint).Where(p=>p!=null).Distinct().OrderBy(p=>p.transform.position.x).ThenBy(p=>p.transform.position.z).ToArray();var policy=manager.gameObject.AddComponent<DistrictDeliveryPolicy>();for(int i=0;i<Mathf.Min(6,points.Length);i++)policy.oldCity.Add(points[Mathf.Min(points.Length-1,Mathf.FloorToInt((i+.5f)*points.Length/6f))]);
var east=all.First(g=>g.name=="Mok East City");var west=all.First(g=>g.name=="Mok West Quarter");west.AddComponent<RobberyDistrict>();
var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scripts/Mok/Art/Districts/Faded yellow.mat");var steel=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scripts/Mok/Art/Districts/Dark steel.mat");var font=AssetDatabase.LoadAssetAtPath<Font>("Assets/Fonts/BMJUA_ttf.ttf");int layer=points[0].gameObject.layer;
DeliveryPoint Install(Transform marker,string id){var root=new GameObject(id+" 배달함");root.transform.SetParent(marker,false);root.layer=layer;var box=root.AddComponent<BoxCollider>();box.center=new Vector3(0,.8f,0);box.size=new Vector3(.8f,1.6f,.45f);var dp=root.AddComponent<DeliveryPoint>();var data=new SerializedObject(dp);data.FindProperty("deliveryPointID").stringValue=id;data.FindProperty("orderManager").objectReferenceValue=manager;data.ApplyModifiedPropertiesWithoutUndo();
void Cube(string n,Vector3 pos,Vector3 size,Material m){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(root.transform,false);g.transform.localPosition=pos;g.transform.localScale=size;g.layer=layer;g.GetComponent<MeshRenderer>().sharedMaterial=m;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());}
Cube("받침",new Vector3(0,.45f,0),new Vector3(.14f,.9f,.14f),steel);Cube("배달함",new Vector3(0,1.1f,0),new Vector3(.7f,.55f,.4f),mat);Cube("번호판",new Vector3(0,1.5f,0),new Vector3(.9f,.25f,.1f),steel);
foreach(int side in new[]{-1,1}){var g=new GameObject("주소");g.transform.SetParent(root.transform,false);g.transform.localPosition=new Vector3(0,1.5f,side*.055f);g.transform.localRotation=Quaternion.Euler(0,side>0?180:0,0);var t=g.AddComponent<TextMesh>();t.font=font;t.fontSize=40;t.characterSize=.023f;t.anchor=TextAnchor.MiddleCenter;t.text=id;t.color=new Color(1,.9f,.7f);g.GetComponent<MeshRenderer>().sharedMaterial=font.material;}return dp;}
int n=0;foreach(var t in east.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("Delivery entrance")).OrderBy(t=>t.name).ToArray())policy.eastCity.Add(Install(t,"신도시 "+(++n).ToString("00")));n=0;foreach(var t in west.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("West entrance")).OrderBy(t=>t.name).ToArray())policy.westQuarter.Add(Install(t,"서안골목 "+(++n).ToString("00")));
var registered=policy.oldCity.Concat(policy.eastCity).Concat(policy.westQuarter).ToArray();list.arraySize=registered.Length;for(int i=0;i<registered.Length;i++)list.GetArrayElementAtIndex(i).objectReferenceValue=registered[i];so.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(policy);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);SceneManager.SetActiveScene(old);if(opened)EditorSceneManager.CloseScene(scene,true);File.WriteAllText("Temp/Mok-district-orders-install.txt","Saved: old="+policy.oldCity.Count+", east="+policy.eastCity.Count+", west="+policy.westQuarter.Count+"; weights=15/50/35; previous destinations="+points.Length);}
}}
#endif
